entries.example:
Zip = New ZipFileWriter("C:\out\invoices.zip");
Zip.Add("C:\out\*.pdf");
Zip.Add("C:\out\register.xlsx");
Zip.Write();

Zip = New ZipFileWriter("C:\out\upload.zip");
Zip.Add("C:\upload", ZIPStorePathMode.StoreRelativePath, ZIPSubDirProcessingMode.ProcessRecursively);
Zip.Write();   // upload\docs\a.pdf goes in as docs/a.pdf

