Reader = New ZipFileReader(source);
foreach (Item in Reader.Items) {
    Message(Item.FullName);
}
Reader.ExtractAll(folder);

entries.syntax_block_ves:
Reader = New ZipFileReader(source);
For Each Item In Reader.Items Do
    Message(Item.FullName);
EndDo;
Reader.ExtractAll(folder);

entries.example:
Reader = New ZipFileReader(Response.GetBodyAsBinaryData());
foreach (Item in Reader.Items) {
    if (Item.Extension == "xml") {
        Reader.Extract(Item, "C:\in");
    }
}
Reader.Close();

foreach (Item in Reader.Items) {
    Message(Item.Path + " | " + Item.Name + " | " + Item.UncompressedSize);
}
